const detections = [];

for (const item of $input.all()) {
  if (item.json.code !== 0) {
    throw new Error(`SSH command failed: ${item.json.stderr}`);
  }

  const output = item.json.stdout || "";

  for (const line of output.split("\n")) {
    if (!line.trim()) continue;

    const response = JSON.parse(line);

    if (response.result) {
      detections.push({
        json: {
          host: response.result.host,
          source_ip: response.result.source_ip,
          timestamp: response.result._time,
          failed_attempts: Number(response.result.failed_attempts),
          alert_type: "Windows Failed Login"
        }
      });
    }
  }
}

return detections;

const publicIPs = [];

for (const item of $input.all()) {
  const ip = String(item.json.source_ip || "").trim();
  const parts = ip.split(".").map(Number);

  // Validate IPv4 address
  if (
    parts.length !== 4 ||
    parts.some(n => !Number.isInteger(n) || n < 0 || n > 255)
  ) continue;

  const [a, b] = parts;

  // Exclude non-public IPv4 ranges
  if (
    a === 0 ||
    a === 10 ||
    a === 127 ||
    a >= 224 ||
    (a === 100 && b >= 64 && b <= 127) ||
    (a === 169 && b === 254) ||
    (a === 172 && b >= 16 && b <= 31) ||
    (a === 192 && b === 168) ||
    (a === 192 && b === 0) ||
    (a === 192 && b === 0 && parts[2] === 2) ||
    (a === 198 && (b === 18 || b === 19)) ||
    (a === 198 && b === 51 && parts[2] === 100) ||
    (a === 203 && b === 0 && parts[2] === 113)
  ) continue;

  publicIPs.push(item);
}

return publicIPs;

const results = [];

for (const item of $input.all()) {
  const data = item.json.data;

  if (!data || !data.ipAddress) {
    throw new Error("Invalid AbuseIPDB response");
  }

  const score = Number(data.abuseConfidenceScore ?? 0);
  const reports = Number(data.totalReports ?? 0);

  let risk_level = "LOW";

  if (score >= 75) {
    risk_level = "HIGH";
  } else if (score >= 25) {
    risk_level = "MEDIUM";
  }

  results.push({
    json: {
      source_ip: data.ipAddress,
      abuse_confidence_score: score,
      total_reports: reports,
      country: data.countryCode ?? "Unknown",
      last_reported: data.lastReportedAt ?? null,
      risk_level: risk_level
    }
  });
}

return results;

